select tpeb.test_plugin_env_binding_id as testPluginEnvBindingId, tpeb.test_project_id as testProjectId, tpeb.test_project_env_id as testProjectEnvId, tpeb.plugin_id as pluginId, tpeb.enabled as enabled, tpeb.config_json as configJson, tpeb.del_status as delStatus, tpeb.create_time as createTime, tpeb.update_time as updateTime from test_plugin_env_binding tpeb where tpeb.del_status = 0
and tpeb.test_project_id = #{testProjectId}
and tpeb.test_project_env_id = #{testProjectEnvId}
and tpeb.plugin_id = #{pluginId}
and tpeb.enabled = #{enabled}
order by tpeb.test_plugin_env_binding_id desc

select count(1)
from test_plugin_env_binding tpeb
where tpeb.del_status = 0

    and tpeb.test_project_id = #{testProjectId}


    and tpeb.test_project_env_id = #{testProjectEnvId}


    and tpeb.plugin_id = #{pluginId}


    and tpeb.enabled = #{enabled}

select tpeb.test_plugin_env_binding_id, tpeb.test_project_id, tpeb.test_project_env_id, tpeb.plugin_id, tpeb.enabled, tpeb.config_json, tpeb.del_status, tpeb.create_time, tpeb.update_time from test_plugin_env_binding tpeb where tpeb.del_status = 0
and tpeb.test_project_id = #{testProjectId}
and tpeb.test_project_env_id = #{testProjectEnvId}
and tpeb.plugin_id = #{pluginId}
and tpeb.enabled = #{enabled}
order by tpeb.test_plugin_env_binding_id desc limit 1
